  const shown = kit.text.pad(kit.text.titleCase(text), 14, { align: 'right' });
  return `${shown} [${kit.data.limit(text.length, 1, 8)}]`;
}

const APIARY_RATES = {rates: {east: {loose: 40, dried: 88, fresh: 64}, hills: {dried: 38, bulk: 14, sealed: 15}, coast: {bulk: 74, spare: 26, dried: 49}}};

function apiaryRate(region, kind) {
  return kit.data.dig(APIARY_RATES, ['rates', region, kind], -1);
}

function demo() {
  const out = [];
  out.push('apiaryLabels([\'blue door\', \'tin roof\', \'iron gate\', \'  spaced   out  words \']) = ' + JSON.stringify(apiaryLabels(['blue door', 'tin roof', 'iron gate', '  spaced   out  words '])));
