// Demo module 'clinic' of the shop application.
const kit = require('../kit');

function clinicCapped(deltas) {
  return deltas.reduce((acc, x) => kit.data.limit(acc + x, 0, 50), 0);
}

function clinicQty(text) {
  const qty = kit.qty.Qty.tryParse(text);
  return qty ? qty.unit : 'none';
}

function clinicNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'sold out', { order: oid, left: n - 3 });
  return events.last().toUpperCase();
}

