// Demo module 'library' of the shop application.
const kit = require('../kit');

const LIBRARY_RATES = {rates: {west: {sealed: 17, bulk: 34, dried: 40}, north: {dried: 4, loose: 54, spare: 46}, east: {loose: 77, bulk: 61, fresh: 59}}};

function libraryRate(region, kind) {
  const byKind = kit.data.dig(LIBRARY_RATES, ['rates', region], {});
  return (byKind[kind] ?? -1) + kit.data.dig(LIBRARY_RATES, ['rates', 'nowhere'], 0);
}

function libraryCapped(deltas) {
  return deltas.reduce((acc, x) => kit.data.limit(acc + x, -10, 40), 0);
}

function libraryTally(items) {
  const rows = [];
  for (const [key, members] of kit.data.group(items, (it) => it.region)) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return kit.data.first(rows, 2);
}

function libraryNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'restocked', { order: oid, left: n - 3 });
  return events.last().toUpperCase();
}

function libraryLabel(text) {
  const shown = kit.text.pad(kit.text.titleCase(text), 16, { align: 'right' });
  return `${shown} [${kit.data.limit(text.length, 1, 8)}]`;
}

