// Demo module 'library' of the shop application.
const oldkit = require('../oldkit');

const LIBRARY_RATES = {rates: {west: {sealed: 17, bulk: 34, dried: 40}, north: {dried: 4, loose: 54, spare: 46}, east: {loose: 77, bulk: 61, fresh: 59}}};

function libraryRate(region, kind) {
  const byKind = oldkit.pick(LIBRARY_RATES, 'rates', region) ?? {};
  return (byKind[kind] ?? -1) + (oldkit.pick(LIBRARY_RATES, 'rates', 'nowhere') ?? 0);
}

function libraryCapped(deltas) {
  return deltas.reduce((acc, x) => oldkit.clamp(acc + x, -10, 40), 0);
}

function libraryTally(items) {
  const rows = [];
  for (const [key, members] of Object.entries(oldkit.groupBy(items, (it) => it.region))) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return oldkit.take(rows, 2);
}

function libraryNote(oid, n) {
  const line = oldkit.log('warn', 'restocked', { order: oid, left: n - 3 });
  return line.toUpperCase();
}

function libraryLabel(text) {
  const shown = oldkit.padLeft(oldkit.title(text), 16);
  return `${shown} [${oldkit.clamp(text.length, 1, 8)}]`;
}

function demo() {
  const out = [];
  out.push('libraryRate(\'west\', \'sealed\') = ' + JSON.stringify(libraryRate('west', 'sealed')));
  out.push('libraryRate(\'north\', \'sealed\') = ' + JSON.stringify(libraryRate('north', 'sealed')));
  out.push('libraryRate(\'atlantis\', \'sealed\') = ' + JSON.stringify(libraryRate('atlantis', 'sealed')));
  out.push('libraryCapped([45, 8, 54, -6, -20, 38]) = ' + JSON.stringify(libraryCapped([45, 8, 54, -6, -20, 38])));
  out.push('libraryTally(rows) = ' + JSON.stringify(libraryTally([{kind: 'dried', region: 'east', unit: 'l'}, {kind: 'dried', region: 'north', unit: 'l'}, {kind: 'dried', region: 'south', unit: 'l'}, {kind: 'fresh', region: 'east', unit: 'kg'}, {kind: 'dried', region: 'south', unit: 'kg'}, {kind: 'dried', region: 'south', unit: 'kg'}, {kind: 'dried', region: 'east', unit: 'kg'}])));
  out.push('libraryNote(\'A98\', 17) = ' + JSON.stringify(libraryNote('A98', 17)));
  out.push('libraryNote(\'B14\', 9) = ' + JSON.stringify(libraryNote('B14', 9)));
  out.push('libraryLabel(\'red lantern\') = ' + JSON.stringify(libraryLabel('red lantern')));
  out.push('libraryLabel(\'x\') = ' + JSON.stringify(libraryLabel('x')));
  out.push('libraryLabel(\'a rather long description of a thing\') = ' + JSON.stringify(libraryLabel('a rather long description of a thing')));
  out.push(...oldkit.flushLog());
  return out;
}

module.exports = { demo };

