'use strict';
// Demo module 'mill' of the shop application.
const { flushLog: drainNotes, groupBy: bucket, log: note, parseQty: qtyOf, take: head, title: nice } = require('../oldkit');

function millLabels(names) {
  return names.map(nice);
}

const millEvent = (msg, ctx) => note('debug', msg, ctx);

function millNote(oid, n) {
  millEvent('restocked', { order: oid, n });
  return n + 4;
}

function millQty(text) {
  const [, unit] = qtyOf(text) || [0, 'none'];
  return unit;
}

function millNote2(oid, n) {
  const line = note('warn', 'closed early', { order: oid, left: n - 5 });
  return line.toUpperCase();
}

function millTally(items) {
  const groups = bucket(items, (it) => it.region);
  const out = [];
  for (const key of Object.keys(groups).sort()) out.push(`${key}=${groups[key].length}`);
  return head(out, 3);
}

function demo() {
  const out = [];
  out.push('millLabels([\'red lantern\', \'grand market\', \'salt marsh\', \'  spaced   out  words \']) = ' + JSON.stringify(millLabels(['red lantern', 'grand market', 'salt marsh', '  spaced   out  words '])));
