  out.push('millQty(\'5\') = ' + JSON.stringify(millQty('5')));
  out.push('millQty(\'lots of it\') = ' + JSON.stringify(millQty('lots of it')));
  out.push('millQty(\'\') = ' + JSON.stringify(millQty('')));
  out.push('millQty(\' 9 L \') = ' + JSON.stringify(millQty(' 9 L ')));
