const BREWERY_RATES = {rates: {hills: {fresh: 32, loose: 14, dried: 48}, west: {dried: 51, bulk: 63, loose: 47}, coast: {fresh: 38, dried: 39, sealed: 68}}};

function breweryRate(region, kind) {
  const byKind = kit.data.dig(BREWERY_RATES, ['rates', region], {});
  return (byKind[kind] ?? 0) + kit.data.dig(BREWERY_RATES, ['rates', 'nowhere'], 0);
}

const BREWERY_HEADER = kit.text.pad('NAME', 12, { align: 'left' }) + kit.text.pad('TOTAL', 8, { align: 'right' });

function breweryHeader() {
  return BREWERY_HEADER + '|';
}

function breweryTally(items) {
  const rows = [];
  for (const [key, members] of kit.data.group(items, (it) => it.region)) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return kit.data.first(rows, 2);
}

function breweryLine(name, qty, cents) {
  return kit.text.pad(name, 14, { align: 'left' }) + kit.text.pad(new kit.money.Money(qty * cents, 'USD').text(), 8, { align: 'right' });
}

function demo() {
  const out = [];
