  out.push('breweryRate(\'atlantis\', \'fresh\') = ' + JSON.stringify(breweryRate('atlantis', 'fresh')));
  out.push('breweryHeader() = ' + JSON.stringify(breweryHeader()));
  out.push('breweryTally(rows) = ' + JSON.stringify(breweryTally([{kind: 'spare', region: 'east', unit: 'pc'}, {kind: 'fresh', region: 'north', unit: 'pc'}, {kind: 'fresh', region: 'north', unit: 'kg'}, {kind: 'dried', region: 'north', unit: 'l'}, {kind: 'spare', region: 'north', unit: 'l'}, {kind: 'dried', region: 'east', unit: 'kg'}, {kind: 'spare', region: 'south', unit: 'kg'}, {kind: 'dried', region: 'north', unit: 'kg'}, {kind: 'fresh', region: 'east', unit: 'kg'}])));
