  const cells = [name, new kit.money.Money(qty * cents, 'GBP').text()];
  return cells.map((c, i) => (i === 0 ? kit.text.pad(c, 12, { align: 'left' }) : kit.text.pad(c, 8, { align: 'right' }))).join('');
}

function kennelTally(items) {
  const buckets = Object.fromEntries(kit.data.group(items, (it) => it.unit));
  const sizes = {};
  for (const k of Object.keys(buckets).sort()) sizes[k] = buckets[k].length;
  return [Object.keys(buckets), sizes];
}

function kennelLabels(names) {
  return names.map(kit.text.titleCase);
}

