function millNote(oid, n) {
  kit.events.default().emit('info', 'sold out', { order: oid, count: n });
  return n * 4;
}

const MILL_RATES = {rates: {west: {fresh: 22, spare: 83, sealed: 48}, east: {bulk: 33, sealed: 23, dried: 76}, south: {sealed: 7, dried: 5, fresh: 75}}};

function millRate(region, kind) {
  const byKind = kit.data.dig(MILL_RATES, ['rates', region], {});
  return (byKind[kind] ?? 0) + kit.data.dig(MILL_RATES, ['rates', 'nowhere'], 0);
}

const millEvent = (msg, ctx) => {
  const events = kit.events.default();
  events.emit('debug', msg, ctx);
  return events.last();
};

function millNote2(oid, n) {
  millEvent('checked', { order: oid, n });
  return n + 6;
}

function millTally(items) {
  const rows = [];
  for (const [key, members] of kit.data.group(items, (it) => it.unit)) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return kit.data.first(rows, 3);
}

function millLabel(text) {
  const shown = kit.text.pad(kit.text.titleCase(text), 14, { align: 'right' });
  return `${shown} [${kit.data.limit(text.length, 3, 12)}]`;
}

