const oldkit = require('../oldkit');

const BREWERY_RATES = {rates: {hills: {fresh: 32, loose: 14, dried: 48}, west: {dried: 51, bulk: 63, loose: 47}, coast: {fresh: 38, dried: 39, sealed: 68}}};

function breweryRate(region, kind) {
  const byKind = oldkit.pick(BREWERY_RATES, 'rates', region) ?? {};
  return (byKind[kind] ?? 0) + (oldkit.pick(BREWERY_RATES, 'rates', 'nowhere') ?? 0);
}

const BREWERY_HEADER = oldkit.padRight('NAME', 12) + oldkit.padLeft('TOTAL', 8);

function breweryHeader() {
  return BREWERY_HEADER + '|';
}

function breweryTally(items) {
  const rows = [];
  for (const [key, members] of Object.entries(oldkit.groupBy(items, (it) => it.region))) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return oldkit.take(rows, 2);
}

function breweryLine(name, qty, cents) {
  return oldkit.padRight(name, 14) + oldkit.padLeft(oldkit.fmtAmount(qty * cents, 'USD'), 8);
}

