  return cells.map((c, i) => (i === 0 ? rpad(c, 10) : lpad(c, 10))).join('');
}

function cooperageLine2(name, qty, cents) {
  const cells = [name, money(qty * cents, 'GBP')];
  return cells.map((c, i) => (i === 0 ? rpad(c, 10) : lpad(c, 8))).join('');
}

function demo() {
