const ok = require('../oldkit');

function estateLine(name, qty, cents) {
  const cells = [name, ok.fmtAmount(qty * cents, 'CHF')];
  return cells.map((c, i) => (i === 0 ? ok.padRight(c, 12) : ok.padLeft(c, 10))).join('');
}

function estateTally(items) {
  const rows = [];
  for (const [key, members] of Object.entries(ok.groupBy(items, (it) => it.unit))) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return ok.take(rows, 4);
}

const ESTATE_FACTORS = {pc: 7, g: 12, box: 8};

function estateQty(text) {
  const parsed = ok.parseQty(text);
  if (parsed === null) return 0;
  const [count, unit] = parsed;
  return count * (ESTATE_FACTORS[unit] ?? 1);
}

function estateNote(oid, n) {
  const line = ok.log('warn', 'sold out', { order: oid, left: n - 7 });
  return line.toUpperCase();
}

