// Demo module 'apiary' of the shop application.
const kit = require('../kit');

function apiaryLine(name, qty, cents) {
  const total = qty * cents;
  return kit.text.pad(name, 12, { align: 'left' }) + kit.text.pad(new kit.money.Money(total, 'CHF').text(), 12, { align: 'right' });
}

const APIARY_FACTORS = {m: 9, kg: 12, box: 5};

function apiaryQty(text) {
  let q;
  try {
    q = kit.qty.Qty.parse(text);
  } catch (e) {
    if (e instanceof kit.qty.QtyError) return 0;
    throw e;
  }
  return q.count * (APIARY_FACTORS[q.unit] ?? 1);
}

function apiaryNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'sold out', { order: oid, left: n - 5 });
  return events.last().toUpperCase();
}

function apiaryLabels(names) {
  return names.map(kit.text.titleCase);
}

function apiaryQty2(text) {
  const qty = kit.qty.Qty.tryParse(text);
  return qty ? qty.count : 0;
}

function demo() {
  const out = [];
  out.push('apiaryLine(\'widget\', 2, 100) = ' + JSON.stringify(apiaryLine('widget', 2, 100)));
