  out.push('apiaryQty2(\'23 g\') = ' + JSON.stringify(apiaryQty2('23 g')));
  out.push('apiaryQty2(\'1x\') = ' + JSON.stringify(apiaryQty2('1x')));
  out.push('apiaryQty2(\'28\') = ' + JSON.stringify(apiaryQty2('28')));
