  return kit.text.pad(name, 10, { align: 'left' }) + kit.text.pad(new kit.money.Money(total, 'CHF').text(), 10, { align: 'right' });
}

function breweryPadded(texts) {
  const right = (t) => kit.text.pad(t, 6, { align: 'right' });
  const left = (t) => kit.text.pad(t, 6, { align: 'left' });
  return texts.map((t) => right(t) + '|' + left(t));
}

function breweryLine2(name, qty, cents) {
  const cells = [name, new kit.money.Money(qty * cents, 'GBP').text()];
  return cells.map((c, i) => (i === 0 ? kit.text.pad(c, 10, { align: 'left' }) : kit.text.pad(c, 10, { align: 'right' }))).join('');
}

function breweryTally(items) {
  const groups = Object.fromEntries(kit.data.group(items, (it) => it.kind));
  const out = [];
  for (const key of Object.keys(groups).sort()) out.push(`${key}=${groups[key].length}`);
  return kit.data.first(out, 2);
}

const BREWERY_RATES = {rates: {hills: {dried: 27, sealed: 71, bulk: 61}, west: {dried: 51, sealed: 19, spare: 64}, coast: {sealed: 57, spare: 71, loose: 6}}};

