  out.push('breweryTally(rows) = ' + JSON.stringify(breweryTally([{kind: 'fresh', region: 'east', unit: 'pc'}, {kind: 'fresh', region: 'south', unit: 'pc'}, {kind: 'spare', region: 'south', unit: 'kg'}, {kind: 'fresh', region: 'east', unit: 'l'}, {kind: 'fresh', region: 'north', unit: 'kg'}])));
