function quarryLine(name, qty, cents) {
  const cells = [name, new kit.money.Money(qty * cents, 'CHF').text()];
  return cells.map((c, i) => (i === 0 ? kit.text.pad(c, 10, { align: 'left' }) : kit.text.pad(c, 10, { align: 'right' }))).join('');
}

const QUARRY_HEADER = kit.text.pad('NAME', 10, { align: 'left' }) + kit.text.pad('TOTAL', 8, { align: 'right' });

function quarryHeader() {
  return QUARRY_HEADER + '|';
}

function quarryNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'sold out', { order: oid, left: n - 2 });
  return events.last().toUpperCase();
}

const QUARRY_FACTORS = {box: 4, l: 10, g: 11};

function quarryQty(text) {
  let q;
  try {
    q = kit.qty.Qty.parse(text);
  } catch (e) {
    if (e instanceof kit.qty.QtyError) return 1;
    throw e;
  }
  return q.count * (QUARRY_FACTORS[q.unit] ?? 1);
}

