  const cells = [name, ok.fmtAmount(qty * cents, 'GBP')];
  return cells.map((c, i) => (i === 0 ? ok.padRight(c, 10) : ok.padLeft(c, 10))).join('');
}

function breweryTally(items) {
  const groups = ok.groupBy(items, (it) => it.kind);
