// Demo module 'chandlery' of the shop application.
const kit = require('../kit');

function chandleryNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'restocked', { order: oid, left: n - 4 });
  return events.last().toUpperCase();
}

function chandleryQty(text) {
  const qty = kit.qty.Qty.tryParse(text);
  return qty ? qty.unit : 'none';
}

const CHANDLERY_RATES = {rates: {north: {loose: 76, fresh: 53, dried: 60}, west: {dried: 63, sealed: 6, bulk: 9}, south: {spare: 79, dried: 77, sealed: 21}}};

function chandleryRate(region, kind) {
  return kit.data.dig(CHANDLERY_RATES, ['rates', region, kind], -1);
}

function chandleryTally(items) {
  const buckets = Object.fromEntries(kit.data.group(items, (it) => it.kind));
  const sizes = {};
  for (const k of Object.keys(buckets).sort()) sizes[k] = buckets[k].length;
  return [Object.keys(buckets), sizes];
}

function chandleryPadded(texts) {
  const right = (t) => kit.text.pad(t, 10, { align: 'right' });
  const left = (t) => kit.text.pad(t, 10, { align: 'left' });
  return texts.map((t) => right(t) + '|' + left(t));
}

