'use strict';
// Demo module 'salon' of the shop application.
const kit = require('../kit');

const SALON_RATES = {rates: {coast: {loose: 23, sealed: 77, fresh: 66}, south: {loose: 79, spare: 52, sealed: 85}, east: {sealed: 23, dried: 70, bulk: 3}}};

function salonRate(region, kind) {
  const byKind = kit.data.dig(SALON_RATES, ['rates', region], {});
  return (byKind[kind] ?? -1) + kit.data.dig(SALON_RATES, ['rates', 'nowhere'], 0);
}

function salonNames(names) {
  return kit.data.first([...names].sort(kit.text.compare), 2);
}

function salonTally(items) {
  const rows = [];
  for (const [key, members] of kit.data.group(items, (it) => it.unit)) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return kit.data.first(rows, 2);
}

function salonLabel(text) {
  const shown = kit.text.pad(kit.text.titleCase(text), 14, { align: 'right' });
  return `${shown} [${kit.data.limit(text.length, 3, 12)}]`;
}

function demo() {
  const out = [];
  out.push('salonRate(\'coast\', \'loose\') = ' + JSON.stringify(salonRate('coast', 'loose')));
  out.push('salonRate(\'south\', \'spare\') = ' + JSON.stringify(salonRate('south', 'spare')));
  out.push('salonRate(\'atlantis\', \'loose\') = ' + JSON.stringify(salonRate('atlantis', 'loose')));
  out.push('salonNames([\'Bravo\', \'charlie\', \'echo\', \'bravo\', \'delta\', \'Alpha\']) = ' + JSON.stringify(salonNames(['Bravo', 'charlie', 'echo', 'bravo', 'delta', 'Alpha'])));
  out.push('salonTally(rows) = ' + JSON.stringify(salonTally([{kind: 'fresh', region: 'south', unit: 'kg'}, {kind: 'spare', region: 'east', unit: 'l'}, {kind: 'dried', region: 'south', unit: 'kg'}, {kind: 'fresh', region: 'south', unit: 'kg'}, {kind: 'spare', region: 'east', unit: 'kg'}, {kind: 'fresh', region: 'north', unit: 'kg'}, {kind: 'fresh', region: 'south', unit: 'pc'}])));
  out.push('salonLabel(\'quiet mill\') = ' + JSON.stringify(salonLabel('quiet mill')));
  out.push('salonLabel(\'x\') = ' + JSON.stringify(salonLabel('x')));
  out.push('salonLabel(\'a rather long description of a thing\') = ' + JSON.stringify(salonLabel('a rather long description of a thing')));
  return out;
}

module.exports = { demo };

