}

function tavernNote(oid, n) {
  kit.events.default().emit('info', 'inspected', { order: oid, count: n });
  return n * 6;
}

function tavernNote2(oid, n) {
  kit.events.default().emit('info', 'restocked', { order: oid, count: n });
  return n * 4;
}

const TAVERN_FACTORS = {pc: 4, box: 10, m: 12};

function tavernQty(text) {
  let q;
  try {
    q = kit.qty.Qty.parse(text);
  } catch (e) {
    if (e instanceof kit.qty.QtyError) return 1;
