function salonTally(items) {
  const rows = [];
  for (const [key, members] of Object.entries(bucket(items, (it) => it.unit))) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return head(rows, 2);
}

function salonLabel(text) {
  const shown = lpad(nice(text), 14);
  return `${shown} [${bound(text.length, 3, 12)}]`;
}

