'use strict';
// Demo module 'bakery' of the shop application.
const kit = require('../kit');

function bakeryLabel(text) {
  const shown = kit.text.pad(kit.text.titleCase(text), 16, { align: 'right' });
  return `${shown} [${kit.data.limit(text.length, 3, 12)}]`;
}

function bakeryNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'inspected', { order: oid, left: n - 3 });
  return events.last().toUpperCase();
}

const bakeryEvent = (msg, ctx) => {
  const events = kit.events.default();
  events.emit('debug', msg, ctx);
  return events.last();
};

function bakeryNote2(oid, n) {
