const oldkit = require('../oldkit');

function stableTally(items) {
  const buckets = oldkit.groupBy(items, (it) => it.region);
  const sizes = {};
  for (const k of Object.keys(buckets).sort()) sizes[k] = buckets[k].length;
  return [Object.keys(buckets), sizes];
}

const STABLE_FACTORS = {g: 5, pc: 3, l: 2};

function stableQty(text) {
  const parsed = oldkit.parseQty(text);
  if (parsed === null) return 1;
  const [count, unit] = parsed;
  return count * (STABLE_FACTORS[unit] ?? 1);
}

