'use strict';
// Demo module 'apiary' of the shop application.
const kit = require('../kit');

function apiaryLabels(names) {
  return names.map(kit.text.titleCase);
}

function apiaryNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'closed early', { order: oid, left: n - 3 });
  return events.last().toUpperCase();
}

const APIARY_RATES = {rates: {south: {dried: 84, fresh: 59, sealed: 80}, hills: {fresh: 38, spare: 53, bulk: 62}, west: {dried: 77, bulk: 83, fresh: 37}}};

function apiaryRate(region, kind) {
  const byKind = kit.data.dig(APIARY_RATES, ['rates', region], {});
  return (byKind[kind] ?? 0) + kit.data.dig(APIARY_RATES, ['rates', 'nowhere'], 0);
}

function apiaryLine(name, qty, cents) {
  const cells = [name, new kit.money.Money(qty * cents, 'GBP').text()];
  return cells.map((c, i) => (i === 0 ? kit.text.pad(c, 14, { align: 'left' }) : kit.text.pad(c, 9, { align: 'right' }))).join('');
}

function demo() {
  const out = [];
  out.push('apiaryLabels([\'old harbour\', \'red lantern\', \'salt marsh\', \'  spaced   out  words \']) = ' + JSON.stringify(apiaryLabels(['old harbour', 'red lantern', 'salt marsh', '  spaced   out  words '])));
  out.push('apiaryNote(\'A16\', 6) = ' + JSON.stringify(apiaryNote('A16', 6)));
  out.push('apiaryNote(\'B45\', 24) = ' + JSON.stringify(apiaryNote('B45', 24)));
  out.push('apiaryRate(\'south\', \'dried\') = ' + JSON.stringify(apiaryRate('south', 'dried')));
  out.push('apiaryRate(\'hills\', \'sealed\') = ' + JSON.stringify(apiaryRate('hills', 'sealed')));
  out.push('apiaryRate(\'atlantis\', \'dried\') = ' + JSON.stringify(apiaryRate('atlantis', 'dried')));
  out.push('apiaryLine(\'plank\', 1, 75) = ' + JSON.stringify(apiaryLine('plank', 1, 75)));
  out.push('apiaryLine(\'widget (large)\', 11, -75) = ' + JSON.stringify(apiaryLine('widget (large)', 11, -75)));
  out.push(...kit.events.default().drain());
  return out;
}

module.exports = { demo };

