'use strict';
// Demo module 'atelier' of the shop application.
const kit = require('../kit');

function atelierLabel(text) {
  const shown = kit.text.pad(kit.text.titleCase(text), 14, { align: 'right' });
  return `${shown} [${kit.data.limit(text.length, 3, 12)}]`;
}

function atelierQty(text) {
  const qty = kit.qty.Qty.tryParse(text);
  return qty ? qty.unit : 'none';
}

function atelierLine(name, qty, cents) {
  const cells = [name, new kit.money.Money(qty * cents, 'GBP').text()];
  return cells.map((c, i) => (i === 0 ? kit.text.pad(c, 10, { align: 'left' }) : kit.text.pad(c, 9, { align: 'right' }))).join('');
}

function atelierNote(oid, n) {
  kit.events.default().emit('info', 'moved', { order: oid, count: n });
  return n * 5;
}

function atelierTally(items) {
  const buckets = Object.fromEntries(kit.data.group(items, (it) => it.kind));
  const sizes = {};
  for (const k of Object.keys(buckets).sort()) sizes[k] = buckets[k].length;
  return [Object.keys(buckets), sizes];
}

function demo() {
  const out = [];
  out.push('atelierLabel(\'old harbour\') = ' + JSON.stringify(atelierLabel('old harbour')));
  out.push('atelierLabel(\'x\') = ' + JSON.stringify(atelierLabel('x')));
  out.push('atelierLabel(\'a rather long description of a thing\') = ' + JSON.stringify(atelierLabel('a rather long description of a thing')));
  out.push('atelierQty(\'9 l\') = ' + JSON.stringify(atelierQty('9 l')));
  out.push('atelierQty(\'5x\') = ' + JSON.stringify(atelierQty('5x')));
