// Demo module 'library' of the shop application.
const kit = require('../kit');

const LIBRARY_FACTORS = {l: 5, kg: 4, pc: 3};

function libraryQty(text) {
  let q;
  try {
    q = kit.qty.Qty.parse(text);
  } catch (e) {
    if (e instanceof kit.qty.QtyError) return 1;
    throw e;
  }
  return q.count * (LIBRARY_FACTORS[q.unit] ?? 1);
}

function libraryTally(items) {
  const rows = [];
  for (const [key, members] of kit.data.group(items, (it) => it.unit)) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return kit.data.first(rows, 3);
}

