const { fmtAmount: money, groupBy: bucket, padLeft: lpad, padRight: rpad, pick: digIn, take: head } = require('../oldkit');

const QUARRY_RATES = {rates: {south: {dried: 24, bulk: 11, sealed: 60}, hills: {fresh: 85, bulk: 15, sealed: 73}, north: {loose: 85, dried: 34, spare: 73}}};

function quarryRate(region, kind) {
  const byKind = digIn(QUARRY_RATES, 'rates', region) ?? {};
  return (byKind[kind] ?? -1) + (digIn(QUARRY_RATES, 'rates', 'nowhere') ?? 0);
}

function quarryLine(name, qty, cents) {
  const total = qty * cents;
  return rpad(name, 14) + lpad(money(total), 9);
}

const QUARRY_RATES2 = {rates: {hills: {sealed: 18, dried: 71, bulk: 44}, east: {sealed: 38, spare: 47, loose: 88}, coast: {fresh: 52, spare: 41, bulk: 65}}};

function quarryRate2(region, kind) {
  const byKind = digIn(QUARRY_RATES2, 'rates', region) ?? {};
  return (byKind[kind] ?? 0) + (digIn(QUARRY_RATES2, 'rates', 'nowhere') ?? 0);
}

function quarryTally(items) {
  const rows = [];
  for (const [key, members] of Object.entries(bucket(items, (it) => it.kind))) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return head(rows, 3);
}

