  const byKind = kit.data.dig(INN_RATES, ['rates', region], {});
  return (byKind[kind] ?? 5) + kit.data.dig(INN_RATES, ['rates', 'nowhere'], 0);
}

function innPadded(texts) {
  const right = (t) => kit.text.pad(t, 8, { align: 'right' });
