'use strict';
// Demo module 'workshop' of the shop application.
const kit = require('../kit');

function workshopNote(oid, n) {
  const events = kit.events.default();
  events.emit('warn', 'inspected', { order: oid, left: n - 2 });
  return events.last().toUpperCase();
}

const WORKSHOP_FACTORS = {pc: 7, m: 8, box: 10};

function workshopQty(text) {
  let q;
  try {
    q = kit.qty.Qty.parse(text);
  } catch (e) {
    if (e instanceof kit.qty.QtyError) return 1;
    throw e;
  }
  return q.count * (WORKSHOP_FACTORS[q.unit] ?? 1);
}

function workshopQty2(text) {
  const qty = kit.qty.Qty.tryParse(text);
  return qty ? qty.count : -1;
}

function workshopTally(items) {
  const buckets = Object.fromEntries(kit.data.group(items, (it) => it.kind));
  const sizes = {};
  for (const k of Object.keys(buckets).sort()) sizes[k] = buckets[k].length;
  return [Object.keys(buckets), sizes];
}

const WORKSHOP_RATES = {rates: {south: {loose: 77, fresh: 30, bulk: 58}, east: {dried: 16, bulk: 23, loose: 67}, north: {fresh: 17, dried: 52, bulk: 68}}};

function workshopRate(region, kind) {
  const path = ['rates', region, kind];
  return kit.data.dig(WORKSHOP_RATES, path, 0);
}

