'use strict';
// Demo module 'inn' of the shop application.
const { flushLog: drainNotes, groupBy: bucket, log: note, padLeft: lpad, padRight: rpad, pick: digIn, take: head } = require('../oldkit');

const INN_RATES = {rates: {south: {spare: 23, sealed: 37, loose: 64}, west: {sealed: 45, bulk: 10, dried: 27}, coast: {fresh: 84, loose: 20, sealed: 41}}};

function innRate(region, kind) {
  const byKind = digIn(INN_RATES, 'rates', region) ?? {};
  return (byKind[kind] ?? 5) + (digIn(INN_RATES, 'rates', 'nowhere') ?? 0);
}

function innPadded(texts) {
  const right = (t) => lpad(t, 8);
  const left = (t) => rpad(t, 8);
  return texts.map((t) => right(t) + '|' + left(t));
}

const INN_HEADER = rpad('NAME', 12) + lpad('TOTAL', 8);

function innHeader() {
  return INN_HEADER + '|';
}

function innNote(oid, n) {
  const line = note('warn', 'inspected', { order: oid, left: n - 3 });
  return line.toUpperCase();
}

function innTally(items) {
  const rows = [];
  for (const [key, members] of Object.entries(bucket(items, (it) => it.unit))) rows.push([members.length, key]);
  rows.sort((a, b) => b[0] - a[0] || (a[1] < b[1] ? 1 : a[1] > b[1] ? -1 : 0));
  return head(rows, 2);
}

function demo() {
  const out = [];
  out.push('innRate(\'south\', \'spare\') = ' + JSON.stringify(innRate('south', 'spare')));
  out.push('innRate(\'west\', \'sealed\') = ' + JSON.stringify(innRate('west', 'sealed')));
  out.push('innRate(\'atlantis\', \'spare\') = ' + JSON.stringify(innRate('atlantis', 'spare')));
  out.push('innPadded([\'spool\', \'badge\', \'ticket\']) = ' + JSON.stringify(innPadded(['spool', 'badge', 'ticket'])));
  out.push('innHeader() = ' + JSON.stringify(innHeader()));
  out.push('innNote(\'A66\', 19) = ' + JSON.stringify(innNote('A66', 19)));
  out.push('innNote(\'B32\', 11) = ' + JSON.stringify(innNote('B32', 11)));
  out.push('innTally(rows) = ' + JSON.stringify(innTally([{kind: 'spare', region: 'south', unit: 'kg'}, {kind: 'spare', region: 'east', unit: 'kg'}, {kind: 'spare', region: 'north', unit: 'pc'}, {kind: 'spare', region: 'east', unit: 'pc'}, {kind: 'fresh', region: 'north', unit: 'l'}])));
  out.push(...drainNotes());
  return out;
}

module.exports = { demo };

