'use strict';

class Events {
  constructor() {
    this.lines = [];
  }

  // Record '{LEVEL} msg key=value ...' (keys sorted).  Returns nothing: see last().
  emit(level, msg, ctx = {}) {
    this.lines.push(`{${level.toUpperCase()}} ${msg}` + Object.keys(ctx).sort().map((k) => ` ${k}=${ctx[k]}`).join(''));
  }

  last() {
    return this.lines[this.lines.length - 1];
  }

  drain() {
    return this.lines.splice(0, this.lines.length);
  }
}

const shared = new Events();

// The process-wide Events instance.
function defaultEvents() {
  return shared;
}

module.exports = { Events, default: defaultEvents };

